// Binary Search — O(log n)
const nums = __ll.array('nums', __input.nums);
const target = __input.target;
let left = 0;
let right = nums.length - 1;

while (left <= right) {
  const mid = Math.floor((left + right) / 2);
  __ll.setVar('left', left);
  __ll.setVar('right', right);
  __ll.setVar('mid', mid);
  const midVal = nums[mid];
  __ll.setVar('midVal', midVal);
  const cmp = __ll.compare(midVal, target, midVal === target);
  if (cmp) {
    __ll.note(`Found target ${target} at index ${mid}`);
    return mid;
  } else if (midVal < target) {
    left = mid + 1;
    __ll.note(`${midVal} < ${target}, search right half`);
  } else {
    right = mid - 1;
    __ll.note(`${midVal} > ${target}, search left half`);
  }
}
return -1;

// Binary Search C++ — O(log n)
#include <iostream>
#include <vector>

using namespace std;

int main() {
  int left = 0;
  int right = nums.size() - 1;

  while (left <= right) {
    int mid = left + (right - left) / 2;
    int midVal = nums[mid];

    if (midVal == target) {
      __ll_note("Found target at index " + __ll_to_json(mid));
      return 0;
    } else if (midVal < target) {
      __ll_note("midVal < target, search right half");
      left = mid + 1;
    } else {
      __ll_note("midVal > target, search left half");
      right = mid - 1;
    }
  }
  return 0;
}
